logger = logging.getLogger(__name__)

_RETRYABLE_PROVIDER_CODES = {429, 500, 502, 503, 504}


def _provider_error_response(exc: genai_errors.APIError) -> Response:
    if exc.code in _RETRYABLE_PROVIDER_CODES:
        return Response(
            {
                "error": (
                    "Our AI assistant is temporarily experiencing "
                    "high demand. Please try again shortly."
                ),
                "code": "AI_PROVIDER_UNAVAILABLE",
                "retryable": True,
            },
            status=status.HTTP_503_SERVICE_UNAVAILABLE,
            headers={"Retry-After": "5"},
        )
    return Response(
        {
            "error": "The AI service could not process your request.",
            "code": "AI_PROVIDER_ERROR",
            "retryable": False,
        },
        status=status.HTTP_502_BAD_GATEWAY,
    )


def _stream_error_frame(code: str, message: str, retryable: bool) -> str:
    return json.dumps(
        {
            "type": "error",
            "error": message,
            "code": code,
            "retryable": retryable,
        }
    ) + "\n"


class NDJSONRenderer(BaseRenderer):
    """
    Renderer for newline-delimited JSON (``application/x-ndjson``).

    DRF's content negotiation only advertises media types that at least one
    configured renderer declares. Without a renderer for
    ``application/x-ndjson`` a request that sends
    ``Accept: application/x-ndjson`` is rejected with ``406 Not Acceptable``
    before the view handler ever runs. Declaring this renderer lets the
    negotiation succeed for the streaming endpoint.

    ``StreamingHttpResponse`` bodies are not passed through ``render()`` -- DRF
    only renders its own ``Response`` objects -- so this method is reached for
    the streaming view's own plain ``Response`` errors and returns a single
    valid NDJSON record for those.
    """

    media_type = "application/x-ndjson"
    format = "ndjson"
    charset = "utf-8"

    def render(self, data, accepted_media_type=None, renderer_context=None):
        if data is None:
            return b""
        if isinstance(data, bytes):
            return data
        if isinstance(data, str):
            return data.encode(self.charset)
        return (json.dumps(data) + "\n").encode(self.charset)


# ---------------------------------------------------------------------------
# Chat view (non-streaming, field-compatible with the old response contract).
# ---------------------------------------------------------------------------


class PortfolioChatView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "portfolio_chat"

    def post(self, request):
        serializer = ChatRequestSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        message = serializer.validated_data["message"]
        session_id = serializer.validated_data.get("session_id")
        visitor_token = serializer.validated_data.get("visitor_token")        # Get or create the session exactly as before.
        if session_id and visitor_token:
            session = ChatSession.objects.filter(
                id=session_id,
                visitor_token=visitor_token,
                is_active=True,
            ).first()
            if not session:
                return Response(
                    {"error": "Invalid or expired chat session."},
                    status=status.HTTP_404_NOT_FOUND,
                )
        else:
            session = ChatSession.objects.create()

        # Load the previous conversation for this session.
        # History is returned to the client as sources, so we keep this
        # contract unchanged.
        history_messages = list(
            session.messages.order_by("-created_at")[:10]
        )
        history_messages.reverse()
        history = [
            {"role": item.role, "content": item.content}
            for item in history_messages
        ]

        # Save the user message as before.
        ChatMessage.objects.create(
            session=session,
            role="user",
            content=message,
        )

        request_start = time.perf_counter()

        try:
            # Build the direct-context prompt and measure retrieval.
            stage_start = time.perf_counter()
            # Limit fetched content so a large portfolio never enlarges the
            # prompt proportionally to the whole dataset.
            prompt = build_gemini_context(
                question=message,
                history=history,
                max_history_turns=10,
            )
            db_time = time.perf_counter() - stage_start

            # Generate a single Gemini response.
            stage_start = time.perf_counter()
            answer = generate_chat_response(
                question=message,
                history=history,
                max_history_turns=10,
                context_prompt=prompt,
            )
            gen_time = time.perf_counter() - stage_start

            # Sources are the project cards for the retrieved context.
            sources = self._build_project_sources(prompt)

            total_time = time.perf_counter() - request_start

            # Save the assistant response as before.
            ChatMessage.objects.create(
                session=session,
                role="assistant",
                content=answer,
                sources=sources,
            )

            logger.info(
                "Portfolio chat: db=%.2fs gen=%.2fs total=%.2fs",
                db_time,
                gen_time,
                total_time,
            )

            return Response(
                {
                    "session_id": str(session.id),
                    "visitor_token": str(session.visitor_token),
                    "answer": answer,
                    "sources": sources,
                    "timing": {
                        "db_ms": round(db_time * 1000, 2),
                        "gemini_ms": round(gen_time * 1000, 2),
                        "total_ms": round(total_time * 1000, 2),
                    },
                },
                status=status.HTTP_200_OK,
            )

        except genai_errors.APIError as exc:
            logger.exception("Gemini API error: %s", exc)
            return _provider_error_response(exc)
        except Exception as exc:
            logger.exception("Portfolio assistant failed: %s", exc)
            return Response(
                {
                    "error": "Something went wrong while generating your response.",
                    "code": "INTERNAL_ASSISTANT_ERROR",
                },
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

    # ---------------------------------------------------------------------------
    # Source cards: the same project-set used by the previous version.
    # ---------------------------------------------------------------------------

    @staticmethod
    def _build_project_sources(prompt: str) -> List[Dict[str, Any]]:
        """
        Extract project source cards from the generated context.

        The plain-text context from build_gemini_context is not a database,
        so we reconstruct the exact project source list it was built from.
        This keeps the frontend contract stable while the squad is free
        to change the internal representation of the prompt.
        """
        # Re-run the same efficient queries used to build the context, so the
        # source cards always match the current data.
        projects = get_public_projects()

        results = []
        for project in projects:
            category = (
                project.category.name if project.category else "—"
            )
            results.append(
                {
                    "slug": project.slug,
                    "title": project.title,
                    "category": category,
                    "client": project.client,
                    "year": project.year,
                    "description": project.description,
                }
            )
        return results


# ---------------------------------------------------------------------------
# Streaming chat view.
#
# The existing non-streaming endpoint is intentionally left untouched so that
# the current frontend keeps working. This endpoint returns a
# newline-delimited JSON stream of conversation fragments, letting the browser
# show the answer progressively. It is available on its own URL so the existing
# frontend's behaviour is not changed.
# ---------------------------------------------------------------------------


class PortfolioChatStreamView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "portfolio_chat"

    # ``application/x-ndjson`` is what the browser streaming client asks for in
    # its Accept header. JSONRenderer stays available so a client that asks for
    # ``application/json`` (or sends no Accept header at all) still gets a
    # negotiable response instead of a 406.
    renderer_classes = [NDJSONRenderer, JSONRenderer]

    def post(self, request):
        serializer = ChatRequestSerializer(data=request.data)
        serializer.is_valid(raise_exception=True)

        message = serializer.validated_data["message"]
        session_id = serializer.validated_data.get("session_id")
        visitor_token = serializer.validated_data.get("visitor_token")

        if session_id and visitor_token:
            session = ChatSession.objects.filter(
                id=session_id,
                visitor_token=visitor_token,
                is_active=True,
            ).first()
            if not session:
                return Response(
                    {"error": "Invalid or expired chat session."},
                    status=status.HTTP_404_NOT_FOUND,
                )
            chat_session = session
        else:
            chat_session = ChatSession.objects.create()

        history_messages = list(
            chat_session.messages.order_by("-created_at")[:10]
        )
        history_messages.reverse()
        history = [
            {"role": item.role, "content": item.content}
            for item in history_messages
        ]

        ChatMessage.objects.create(
            session=chat_session,
            role="user",
            content=message,
        )

        # Build the direct-context prompt for streaming.
        prompt = build_gemini_context(
            question=message,
            history=history,
            max_history_turns=10,
        )

        # The stream leads with the session identifiers so the client can keep
        # sending the same session on the next message. Without this frame the
        # streaming client would start a fresh conversation every turn.
        session_frame = (
            json.dumps(
                {
                    "type": "session",
                    "session_id": str(chat_session.id),
                    "visitor_token": str(chat_session.visitor_token),
                }
            )
            + "\n"
        )

        chunks = self._stream_response(prompt, chat_session, history, message)
        try:
            first_chunk = next(chunks)
        except StopIteration:
            return StreamingHttpResponse(
                (session_frame,),
                content_type="application/x-ndjson",
            )
        except genai_errors.APIError as exc:
            logger.exception("Gemini streaming API error: %s", exc)
            return _provider_error_response(exc)
        except Exception:
            logger.exception("Portfolio assistant streaming failed")
            return Response(
                {
                    "error": "Something went wrong while generating your response.",
                    "code": "INTERNAL_ASSISTANT_ERROR",
                },
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        return StreamingHttpResponse(
            chain((session_frame, first_chunk), chunks),
            content_type="application/x-ndjson",
        )

    def _stream_response(
        self,
        prompt: str,
        session: ChatSession,
        history: List[Dict[str, str]],
        user_message: str,
    ):
        """
        Stream generated text back to the client.

        We do NOT create a second model instance per chunk. The single Gemini
        client is reused, and the stream is consumed in a generator that only
        yields text as it arrives.
        """
        from .utils import (
            _format_assistant_chat_chunks,
            get_gemini_client,
        )

        client = get_gemini_client()
        primary_model = _select_gemini_chat_model()
        fallback_model = getattr(
            settings,
            "GEMINI_CHAT_FALLBACK_MODEL",
            "",
        ).strip()

        # Prepare the streaming generation. We use the same config as the
        # non-streaming path, plus a higher token budget for the live UI.
        config = types.GenerateContentConfig(
            thinking_config=types.ThinkingConfig(thinking_level="low"),
            max_output_tokens=1500,
        )

        attempted_models = [primary_model]
        if fallback_model and fallback_model != primary_model:
            attempted_models.append(fallback_model)

        for model_index, model in enumerate(attempted_models):
            full_answer = []
            emitted = False
            completed = False
            try:
                response = client.models.generate_content_stream(
                    model=model,
                    contents=prompt,
                    config=config,
                )
                for chunk in response:
                    if chunk.text:
                        full_answer.append(chunk.text)
                    for event in _format_assistant_chat_chunks(chunk):
                        emitted = True
                        yield json.dumps(event) + "\n"
                completed = True
                break
            except genai_errors.APIError as exc:
                can_fallback = (
                    model_index == 0
                    and not emitted
                    and exc.code in _RETRYABLE_PROVIDER_CODES
                    and len(attempted_models) > 1
                )
                if can_fallback:
                    logger.warning(
                        "Gemini streaming model %s unavailable; trying fallback.",
                        model,
                    )
                    continue
                if not emitted:
                    raise
                logger.exception("Gemini streaming API error: %s", exc)
                response = _provider_error_response(exc)
                yield _stream_error_frame(
                    response.data["code"],
                    response.data["error"],
                    response.data.get("retryable", False),
                )
                return
            except Exception:
                if not emitted:
                    raise
                logger.exception("Portfolio assistant streaming failed")
                yield _stream_error_frame(
                    "INTERNAL_ASSISTANT_ERROR",
                    "Something went wrong while generating your response.",
                    False,
                )
                return
            finally:
                assistant_text = "".join(full_answer)
                if completed and assistant_text:
                    ChatMessage.objects.create(
                        session=session,
                        role="assistant",
                        content=assistant_text,
                    )


# ---------------------------------------------------------------------------
# Natural-language project search.
#
# A visitor describes what they are looking for in their own words ("moody
# black and white fashion work") and Gemini ranks the published projects
# against it. The response is a plain list of project cards, so the work page
# can render it with the components it already has.
# ---------------------------------------------------------------------------


class ProjectSearchView(APIView):
    permission_classes = [AllowAny]
    throttle_classes = [ScopedRateThrottle]
    throttle_scope = "portfolio_search"

    def get(self, request):
        serializer = ProjectSearchRequestSerializer(data=request.query_params)
        serializer.is_valid(raise_exception=True)
        query = serializer.validated_data["query"]

        try:
            projects = search_public_projects(query)
        except genai_errors.APIError as exc:
            logger.exception("Gemini project search error: %s", exc)
            return _provider_error_response(exc)
        except Exception as exc:
            logger.exception("Project search failed: %s", exc)
            return Response(
                {
                    "error": "Search is unavailable right now. Please try again shortly.",
                    "code": "INTERNAL_SEARCH_ERROR",
                },
                status=status.HTTP_500_INTERNAL_SERVER_ERROR,
            )

        return Response(
            {
                "query": query,
                "count": len(projects),
                "results": [
                    {
                        "slug": project.slug,
                        "title": project.title,
                        "client": project.client,
                        "category": (
                            project.category.name if project.category else None
                        ),
                        "year": project.year,
                        "description": project.description,
                        "cover_image": project.cover_image,
                    }
                    for project in projects
                ],
            },
            status=status.HTTP_200_OK,
        )
